function getRealIndex(chat, displayIdx) {
  if (!chat) return displayIdx;
  let count = -1;
  for (let i = 0; i < chat.messages.length; i++) {
    if (chat.messages[i].role !== 'system') count++;
    if (count === displayIdx) return i;
  }
  return displayIdx;
}

