    try { return katex.renderToString(tex.trim(), { displayMode: false, throwOnError: false }); } catch { return m; }
  });

  // Restore code blocks
  html = html.replace(/%%CODE(\d+)%%/g, (m, i) => codeBlocks[parseInt(i)] || m);
  return html;
}

