    timerEl.textContent = "Race ended!";
    updateGameVisibility();
    return;
  }
  timerEl.textContent = `Time left: ${(ms / 1000).toFixed(1)}s`;
  updateGameVisibility();
  requestAnimationFrame(updateTimer);
}

