    await s3Client.send(new CopyObjectCommand({
      Bucket: destBucket,
      Key: destKey,
      CopySource: encodeCopySource(file.bucket, file.s3Key),
      ContentType: file.fileType,
      MetadataDirective: "COPY"
    }));

    await s3Client.send(new DeleteObjectCommand({
      Bucket: file.bucket,
      Key: file.s3Key
    }));

