const CDN_URL = process.env.CDN_URL;
const DISCORD_BOT_TOKEN = process.env.DISCORD_BOT_TOKEN;
const DISCORD_CHANNEL_ID = process.env.DISCORD_CHANNEL_ID;

const app = express();
const upload = multer({ dest: '/tmp/uploads/' });

app.use(express.json());
