  }

  fetch(OAUTH_USER_INFO_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${access_token}`,
    },
  })
    .then(response => {
      if (!response.ok) {
        return next();
      }
      return response.json();
    })
    .then(userData => {
      const { roles } = userData;

      if (roles.includes('standardUser') || roles.includes('adminUser')) {
