async function getWindowsPassword(username, instanceId) {
  try {
    const sshKeyName = `${username}-ssh-key.pem`;
    const keyFilePath = path.join('/tmp', sshKeyName);

    const command = new GetObjectCommand({
      Bucket: S3_BUCKET_NAME,
      Key: sshKeyName,
    });

    const { Body } = await s3Client.send(command);
    const privateKeyPem = await Body.transformToString();
    await fs.writeFile(keyFilePath, privateKeyPem);

    const passwordCommand = new GetPasswordDataCommand({ InstanceId: instanceId });
    const response = await ec2Client.send(passwordCommand);

    if (!response.PasswordData) {
      throw new Error('No password data returned from AWS.');
    }

    const encryptedPassword = Buffer.from(response.PasswordData, 'base64');
    const privateKey = forge.pki.privateKeyFromPem(privateKeyPem);
    const decryptedPassword = privateKey.decrypt(encryptedPassword.toString('binary'), 'RSAES-PKCS1-V1_5');

    await fs.unlink(keyFilePath);

    return decryptedPassword;
  } catch (error) {
    console.error('Error retrieving or decrypting Windows password:', error);
    throw new Error('Unable to retrieve or decrypt the Windows password.');
  }
}

