def check_dependencies():
    """Check if AWS CLI, pip, zip, and npm are installed."""
    has_aws = True
    has_pip = True
    has_npm = True

    if shutil.which("aws") is None:
        has_aws = False

    if shutil.which("pip") is None:
        has_pip = False

    if shutil.which("npm") is None:
        has_npm = False

    if not has_aws:
        click.echo("Please install the AWS CLI first")
        sys.exit(1)

    if not has_pip:
        click.echo("Please install pip first")
        sys.exit(1)

    if not has_npm:
        click.echo("Please install npm first")
        sys.exit(1)


def check_aws_signed_in():
    """Check if the user is signed in to AWS CLI."""
    try:
        subprocess.run(
            ["aws", "sts", "get-caller-identity"], check=True, capture_output=True
        )
    except subprocess.CalledProcessError:
        click.echo("Please sign in to the AWS CLI first")
        sys.exit(1)


def get_default_region():
    """Get the default AWS region from the AWS CLI configuration or environment variable."""
    result = subprocess.run(
        ["aws", "configure", "get", "region"],
        capture_output=True,
        text=True,
    )

    if result.returncode == 0 and result.stdout.strip():
        region = result.stdout.strip()
    else:
        region = os.getenv("AWS_DEFAULT_REGION")
        if region:
            click.echo(f"Using AWS_DEFAULT_REGION: {region}")
        else:
            click.echo("No default region configured, using us-east-1 as default.")
            region = "us-east-1"

    return region


