import { createRemoteJWKSet, jwtVerify } from 'jose';

const JWKS = createRemoteJWKSet(new URL('https://oneidp.ch/.well-known/jwks.json'));

const { payload } = await jwtVerify(idToken, JWKS, {
  algorithms: ['RS256'],
