    // The registration regex rejects `?`, `&`, `=` and `%`.
    assert.throws(
      () => new OneidpClient({ ...base, redirectUri: 'https://app.example.com/cb?tenant=acme' }),
      ConfigurationError,
    );
    assert.throws(
      () => new OneidpClient({ ...base, redirectUri: 'https://app.example.com/cb~1' }),
