      const app = appByClientId.get(consent.clientId);
      return {
        appName: app.oauthAppName,
        clientId: consent.clientId,
        redirectUri: app.redirectUri,
        consentedScopes: consent.consentedScopes,
        firstAuthAt: consent.firstAuthAt,
