function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (ch) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch] || ch)
  );
}

function wrapHtml(inner) {
  return `<html><body>${inner}</body></html>`;
}

