function checkAuth(req, res, next) {
  const token = req.cookies.wt_session;
  const wantsJson = req.path.startsWith('/api/') || req.path === '/username' ||
    req.path === '/readings' || req.path === '/latest-kwh' ||
    req.path === '/api/price' ||
    (req.headers.accept && req.headers.accept.includes('application/json'));

  if (!token) {
    return wantsJson
