      : res.redirect('/login');
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    req.username = decoded.username;
    req.role = decoded.role || 'user';
    next();
  } catch {
    res.clearCookie('wt_session');
    return wantsJson
      ? res.status(401).json({ message: 'Session expired.' })
      : res.redirect('/login');
  }
}

