app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ message: 'Username and password required.' });

  const name = username.trim().toLowerCase();

  let user = await getUser(name);

  // Auto-create admin on first login attempt
  if (!user && name === 'admin') {
    if (password.length < 4) return res.status(400).json({ message: 'Passwort: mind. 4 Zeichen.' });
    const hash = await bcrypt.hash(password, 10);
    await putUser('admin', hash, 'admin');
    user = await getUser('admin');
    console.log('Admin account auto-created on first login.');
  }

  if (!user) return res.status(401).json({ message: 'Ungültige Anmeldedaten.' });

  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) return res.status(401).json({ message: 'Ungültige Anmeldedaten.' });

  const token = jwt.sign(
    { username: user.username, role: user.role },
    JWT_SECRET,
    { expiresIn: '365d' }
  );

  res.cookie('wt_session', token, {
    httpOnly: true,
    secure: true,
    sameSite: 'Strict',
    maxAge: 365 * 24 * 60 * 60 * 1000 // 365 days
  });

  return res.json({ username: user.username, role: user.role });
});

